SELECT DATE_FORMAT(t.submit_time, '%Y-%m-%d') AS date,
       COUNT(*)                               AS count
FROM ticket t
WHERE t.deleted = 0
  AND t.tenant_id = #{tenantId}
  AND t.submit_time >= #{start}
  AND t.submit_time < #{end}
GROUP BY DATE_FORMAT(t.submit_time, '%Y-%m-%d')
ORDER BY date

SELECT DATE_FORMAT(DATE_SUB(t.submit_time, INTERVAL WEEKDAY(t.submit_time) DAY), '%Y-%m-%d') AS date,
       COUNT(*)                                                                             AS count
FROM ticket t
WHERE t.deleted = 0
  AND t.tenant_id = #{tenantId}
  AND t.submit_time >= #{start}
  AND t.submit_time < #{end}
GROUP BY DATE_FORMAT(DATE_SUB(t.submit_time, INTERVAL WEEKDAY(t.submit_time) DAY), '%Y-%m-%d')
ORDER BY date

SELECT c.name     AS name,
       COUNT(*)   AS count
FROM ticket t
         JOIN ticket_category c ON c.id = t.category_id
WHERE t.deleted = 0
  AND t.tenant_id = #{tenantId}
  AND t.submit_time >= #{start}
  AND t.submit_time < #{end}
GROUP BY c.id, c.name
ORDER BY count DESC

SELECT b.name     AS name,
       COUNT(*)   AS count
FROM ticket t
         JOIN building b ON b.id = t.building_id
WHERE t.deleted = 0
  AND t.tenant_id = #{tenantId}
  AND t.submit_time >= #{start}
  AND t.submit_time < #{end}
GROUP BY b.id, b.name
ORDER BY count DESC

SELECT CAST(t.urgency AS CHAR) AS name,
       COUNT(*)                AS count
FROM ticket t
WHERE t.deleted = 0
  AND t.tenant_id = #{tenantId}
  AND t.submit_time >= #{start}
  AND t.submit_time < #{end}
GROUP BY t.urgency
ORDER BY count DESC
